import React, { useState, useEffect } from 'react';

const fullImageUrl = "https://res.cloudinary.com/dbphdr1su/image/upload/v1764483511/baptist_church_vnlael.jpg";
const placeholderImageUrl = "https://res.cloudinary.com/dbphdr1su/image/upload/v1764483511/baptist_church_vnlael.jpg";

const Hero: React.FC = () => {
    const [offsetY, setOffsetY] = useState(0);
    const [imageLoaded, setImageLoaded] = useState(false);
    const [currentImage, setCurrentImage] = useState(placeholderImageUrl);

    const handleScroll = () => setOffsetY(window.pageYOffset);

    useEffect(() => {
        window.addEventListener('scroll', handleScroll);
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    useEffect(() => {
        const img = new Image();
        img.src = fullImageUrl;
        img.onload = () => {
            setImageLoaded(true);
            setCurrentImage(fullImageUrl);
        };
        img.onerror = () => {
            console.error('Failed to load hero image');
            setCurrentImage(placeholderImageUrl);
        };
    }, []);

    const SliderDots = () => (
      <div className="absolute left-6 top-1/2 -translate-y-1/2 z-10 hidden md:flex flex-col space-y-3">
        <button className="w-2.5 h-2.5 rounded-full border border-white/50 transition-colors hover:bg-white"></button>
        <button className="w-2.5 h-2.5 rounded-full border border-white bg-white transition-colors hover:bg-white"></button>
        <button className="w-2.5 h-2.5 rounded-full border border-white/50 transition-colors hover:bg-white"></button>
      </div>
    );

    return (
        <section id="home" className="relative h-screen flex items-center justify-center text-white text-center overflow-hidden">
            <div
                className="absolute top-0 left-0 w-full h-full bg-cover bg-center transition-all duration-1000 ease-out"
                style={{
                    backgroundImage: `url(${currentImage})`,
                    transform: `translateY(${offsetY * 0.4}px)`,
                    filter: 'brightness(0.6)',
                    backgroundSize: 'cover',
                    backgroundPosition: 'center'
                }}
            />
            <div className="absolute top-0 left-0 w-full h-full bg-black/40" />

            <SliderDots />

            <div className="relative z-10 px-6 transition-opacity duration-1000 ease-in opacity-0 animate-fadeIn max-w-4xl flex flex-col items-center">
                <p className="text-lg md:text-xl font-sans mb-4 tracking-[0.3em] uppercase text-white/90">
                    Jesus is the Way, the Truth, and the Life
                </p>
                <h1 className="text-4xl md:text-7xl lg:text-8xl font-serif font-bold mb-10 drop-shadow-2xl leading-tight">
                    Welcome to Our <br /> <span className="text-dusty-rose">Spiritual Home</span>
                </h1>
                <div className="flex flex-col sm:flex-row space-y-4 sm:space-y-0 sm:space-x-6">
                    <a
                        href="#mission"
                        className="bg-dusty-rose text-white px-12 py-4 text-xs font-bold tracking-[0.2em] uppercase rounded-sm hover:bg-white hover:text-deep-blue-gray transition-all duration-300 transform hover:scale-105 shadow-xl"
                    >
                        Learn More
                    </a>
                    <a
                        href="#services"
                        className="bg-white/10 backdrop-blur-sm border border-white/30 text-white px-12 py-4 text-xs font-bold tracking-[0.2em] uppercase rounded-sm hover:bg-white hover:text-deep-blue-gray transition-all duration-300 transform hover:scale-105 shadow-xl"
                    >
                        Visit Us
                    </a>
                </div>
            </div>

            {/* Scroll Indicator */}
            <div className="absolute bottom-10 left-1/2 -translate-x-1/2 z-10 animate-bounce">
                <svg className="w-6 h-6 text-white/60" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 14l-7 7-7-7" />
                </svg>
            </div>

            {/* Loading indicator */}
            {!imageLoaded && (
                <div className="absolute inset-0 flex items-center justify-center z-5 bg-gray-900">
                    <div className="text-white text-lg tracking-widest animate-pulse uppercase">Entering Presence...</div>
                </div>
            )}

            <style>{`
                @keyframes fadeIn {
                    to {
                        opacity: 1;
                    }
                }
                .animate-fadeIn {
                    animation: fadeIn 1.5s forwards;
                    animation-delay: 0.5s;
                }
            `}</style>
        </section>
    );
};

export default Hero;
